export const POSTER_SECONDS = 3;
export const MOMENT_SECONDS = 15;
const WIDTH = 328.607;
const HEIGHT = 274;
const clamp = (value) => Math.max(0, Math.min(1, value));
const smooth = (value) => { const t = clamp(value); return t * t * (3 - 2 * t); };

function cursorPosition(seconds, stops) {
	const phase = Math.max(0, seconds - POSTER_SECONDS) % 12;
	const next = stops.findIndex(([at]) => at > phase);
	const [start, x, y] = stops[next - 1];
	const [end, toX, toY] = stops[next];
	const progress = smooth((phase - start) / (end - start));
	return [x + (toX - x) * progress, y + (toY - y) * progress];
}

const AGENT_STOPS = [[0, 0, 0], [1.4, 0, 0], [3.8, 6, -4], [6.2, 6, -4], [8.6, -3, 2], [10, -3, 2], [12, 0, 0]];
const HUMAN_STOPS = [[0, 0, 0], [2.6, 0, 0], [5, -4, -3], [7.2, -4, -3], [9.6, 3, 4], [10.4, 3, 4], [12, 0, 0]];

export function multiplayerFrame(seconds) {
	const time = Math.max(0, seconds);
	return {
		outline: smooth(time / 1.5),
		circles: Array.from({ length: 6 }, (_, index) => smooth((time - 0.24 - index * 0.13) / 1.05)),
		ring: smooth((time - 1.05) / 1.1),
		agentTrail: smooth((time - 1.8) / 0.65),
		humanTrail: smooth((time - 2.1) / 0.65),
		agentOpacity: smooth((time - 1.5) / 0.35),
		humanOpacity: smooth((time - 1.85) / 0.35),
		agent: cursorPosition(time, AGENT_STOPS),
		human: cursorPosition(time, HUMAN_STOPS),
	};
}

export function multiplayerTime(seconds, { play = "live", length = MOMENT_SECONDS, rest = 1.5 } = {}) {
	const time = Math.max(0, seconds);
	if (play === "live") return time;
	return Math.min(play === "loop" ? time % (length + rest) : time, length);
}

const asset = (name) => new URL(`/1p/finale-pieces/assets/multiplayer/${name}.svg`, document.baseURI).href;
const stylesheet = new URL("/1p/finale-pieces/multiplayer.css", document.baseURI).href;
const SVG_NS = "http://www.w3.org/2000/svg";
let instance = 0;

function setAttribute(node, name, value) {
	const next = String(value);
	if (node.getAttribute(name) !== next) node.setAttribute(name, next);
}

function draw(node, progress) {
	setAttribute(node, "stroke-dasharray", progress === 1 ? "none" : "1");
	setAttribute(node, "stroke-dashoffset", 1 - progress);
	setAttribute(node, "opacity", progress > 0 ? 1 : 0);
}

class MultiplayerCollaboration extends HTMLElement {
	static observedAttributes = ["time", "paused", "scale", "appearance", "surface", "play", "rest", "length"];
	#styles;
	#stage;
	#lines;
	#circles;
	#agent;
	#human;
	#frame = 0;
	#elapsed = 0;
	#lastTick = null;
	#visible = true;
	#observer;
	#motion = matchMedia("(prefers-reduced-motion: reduce)");
	#refresh = () => this.redraw();

	connectedCallback() {
		if (!document.querySelector("link[data-multiplayer-style]")) {
			const link = document.createElement("link");
			link.rel = "stylesheet";
			link.href = stylesheet;
			link.dataset.multiplayerStyle = "";
			document.head.append(link);
		}
		if (!this.#stage) this.#build();
		this.#motion.addEventListener("change", this.#refresh);
		document.addEventListener("visibilitychange", this.#refresh);
		this.#observer = new IntersectionObserver(([entry]) => {
			this.#visible = entry.isIntersecting;
			this.redraw();
		});
		this.#observer.observe(this);
		this.redraw();
	}

	disconnectedCallback() {
		cancelAnimationFrame(this.#frame);
		this.#lastTick = null;
		this.#observer?.disconnect();
		this.#motion.removeEventListener("change", this.#refresh);
		document.removeEventListener("visibilitychange", this.#refresh);
	}

	attributeChangedCallback() { this.redraw(); }
	get pieceStyles() { return this.#styles; }
	set pieceStyles(value) { this.#styles = value; this.redraw(); }

	#build() {
		this.setAttribute("role", "img");
		this.setAttribute("aria-label", "Multiplayer. Agent and Human cursors collaborate across six overlapping dotted circles, a rounded hexagon, and a green accented circle.");
		this.#stage = document.createElement("div");
		this.#stage.className = "multiplayer-stage";
		this.#stage.setAttribute("aria-hidden", "true");
		this.#stage.innerHTML = `<div class="multiplayer-art">
			<div class="multiplayer-construction">${CONSTRUCTION_SVG}</div>
			<div class="multiplayer-outline">${OUTLINE_SVG}</div>
			<div class="multiplayer-agent-trail">${AGENT_TRAIL_SVG}</div>
			<div class="multiplayer-human-ring">${HUMAN_RING_SVG}</div>
			<div class="multiplayer-human-trail">${HUMAN_TRAIL_SVG}</div>
			<div class="multiplayer-cursor multiplayer-agent"><span class="multiplayer-tag"><img src="${asset("agent-icon")}" alt="">Agent</span><img class="multiplayer-pointer" src="${asset("agent-cursor")}" alt=""></div>
			<div class="multiplayer-cursor multiplayer-human"><img class="multiplayer-pointer" src="${asset("human-cursor")}" alt=""><span class="multiplayer-tag"><img src="${asset("human-avatar")}" alt="">Human</span></div>
		</div>`;
		const prefix = `multiplayer-${++instance}`;
		this.#stage.querySelectorAll("svg").forEach((svg, index) => {
			const ids = new Map();
			svg.querySelectorAll("[id]").forEach((node, shape) => {
				const id = `${prefix}-${index}-${shape}`;
				ids.set(node.id, id);
				node.id = id;
			});
			svg.querySelectorAll("[stroke]").forEach((node) => {
				const id = node.getAttribute("stroke").match(/^url\(#(.+)\)$/)?.[1];
				if (id) node.setAttribute("stroke", `url(#${ids.get(id)})`);
			});
		});
		const construction = this.#stage.querySelector(".multiplayer-construction svg");
		const defs = construction.querySelector("defs");
		this.#circles = [...construction.querySelectorAll("path")].map((node, index) => {
			// Animate a solid mask so the original dotted strokes and gradients stay intact.
			const mask = document.createElementNS(SVG_NS, "mask");
			mask.id = `${prefix}-reveal-${index}`;
			for (const [name, value] of Object.entries({ maskUnits: "userSpaceOnUse", x: -2, y: -2, width: 240, height: 257 })) mask.setAttribute(name, value);
			const reveal = node.cloneNode();
			reveal.removeAttribute("id");
			reveal.setAttribute("stroke", "white");
			reveal.setAttribute("stroke-width", "3");
			reveal.setAttribute("pathLength", "1");
			mask.append(reveal);
			defs.append(mask);
			node.setAttribute("mask", `url(#${mask.id})`);
			return reveal;
		});
		this.#lines = ["outline", "human-ring", "agent-trail", "human-trail"].map((name) => {
			const node = this.#stage.querySelector(`.multiplayer-${name} path`);
			node.setAttribute("pathLength", "1");
			return node;
		});
		this.#agent = this.#stage.querySelector(".multiplayer-agent");
		this.#human = this.#stage.querySelector(".multiplayer-human");
		this.replaceChildren(this.#stage);
	}

	#number(name, fallback) {
		const value = this.getAttribute(name);
		return value !== null && Number.isFinite(Number(value)) ? Number(value) : fallback;
	}

	#paint() {
		const settings = this.#styles?.multiplayer ?? {};
		const scale = Math.max(0.01, this.#number("scale", 1));
		this.style.width = `${WIDTH * scale}px`;
		this.style.height = `${HEIGHT * scale}px`;
		this.#stage.style.transform = `scale(${scale})`;
		const surface = this.getAttribute("surface");
		this.#stage.classList.toggle("no-surface", surface === "off" || (surface !== "on" && settings.surface === false));
		const reduced = this.#motion.matches;
		const time = reduced ? POSTER_SECONDS : this.#number("time", this.#elapsed);
		const play = reduced ? "live" : this.getAttribute("play") ?? settings.play ?? "live";
		const length = Math.max(0.1, this.#number("length", settings.length ?? MOMENT_SECONDS));
		const pose = multiplayerFrame(multiplayerTime(time, { play, length, rest: Math.max(0, this.#number("rest", settings.rest ?? 1.5)) }));
		[pose.outline, pose.ring, pose.agentTrail, pose.humanTrail].forEach((progress, index) => draw(this.#lines[index], progress));
		pose.circles.forEach((progress, index) => draw(this.#circles[index], progress));
		this.#agent.style.opacity = String(pose.agentOpacity);
		this.#human.style.opacity = String(pose.humanOpacity);
		this.#agent.style.transform = `translate(${pose.agent[0]}px, ${pose.agent[1]}px)`;
		this.#human.style.transform = `translate(${pose.human[0]}px, ${pose.human[1]}px)`;
		return play !== "once" || time < length;
	}

	redraw() {
		cancelAnimationFrame(this.#frame);
		this.#lastTick = null;
		if (!this.isConnected || !this.#stage) return;
		const moving = this.#paint();
		if (!moving || this.hasAttribute("time") || this.hasAttribute("paused") || this.#motion.matches || !this.#visible || document.hidden) return;
		const tick = (now) => {
			if (this.#lastTick !== null) this.#elapsed += (now - this.#lastTick) / 1000;
			this.#lastTick = now;
			if (this.#paint()) this.#frame = requestAnimationFrame(tick);
		};
		this.#frame = requestAnimationFrame(tick);
	}
}

if (!customElements.get("multiplayer-collaboration")) customElements.define("multiplayer-collaboration", MultiplayerCollaboration);
